-- supabase/contenido-semilla.sql
-- Lo generó scripts/semilla-contenido.mjs con lo que la web traía en el código. Va después de admin.sql. Cada sección
-- entra solo si está vacía, así que correrlo de nuevo no pisa lo que ya se cambió en /admin.

-- cifras: 4
insert into web_bonding.contenido (seccion, datos, orden)
select 'cifras', v.datos, v.orden from (values
  ($wb${"n":30,"suffix":"+","label":"proyectos\nentregados"}$wb$::jsonb, 1),
  ($wb${"n":8,"suffix":"","label":"industrias\natendidas"}$wb$::jsonb, 2),
  ($wb${"n":2,"suffix":"","label":"países\n(VE · Latam)"}$wb$::jsonb, 3),
  ($wb${"n":100,"suffix":"%","label":"código\na medida"}$wb$::jsonb, 4)
) as v(datos, orden)
where not exists (select 1 from web_bonding.contenido c where c.seccion = 'cifras');

