-- preguntas: 6
insert into web_bonding.contenido (seccion, datos, orden)
select 'preguntas', v.datos, v.orden from (values
  ($wb${"q":"¿Dónde está ubicada Web Bonding?","a":"Web Bonding tiene sede en Acarigua–Araure, estado Portuguesa, Venezuela. Atendemos clientes presenciales en la región y trabajamos de forma remota con empresas de toda Venezuela y Latinoamérica."}$wb$::jsonb, 1),
  ($wb${"q":"¿Qué tipo de proyectos desarrollan?","a":"Construimos páginas web, e-commerce, aplicaciones móviles iOS y Android, sistemas ERP/CRM, agentes de Inteligencia Artificial, chatbots WhatsApp, soluciones IoT, automatización industrial y software a medida para cualquier industria."}$wb$::jsonb, 2),
  ($wb${"q":"¿Cuánto cuesta hacer una página web o una app en Venezuela?","a":"Una landing page profesional inicia desde aproximadamente 300 USD; un e-commerce desde 1.200 USD; y una aplicación móvil multiplataforma desde 2.700 USD. Todos los proyectos se cotizan a medida según funcionalidades. Solicita una cotización por WhatsApp al +58 422 057 9731."}$wb$::jsonb, 3),
  ($wb${"q":"¿Trabajan con empresas fuera de Acarigua y Araure?","a":"Sí. Aunque nuestra sede está en Acarigua–Araure, Portuguesa, atendemos remotamente a clientes de Barquisimeto, Caracas, Valencia, Maracay, Maracaibo y toda Latinoamérica (Colombia, México, Argentina, entre otros)."}$wb$::jsonb, 4),
  ($wb${"q":"¿Qué tecnologías usan?","a":"Desarrollamos con React, Next.js, TypeScript, Node.js, Python, Flutter, Capacitor, Supabase, MongoDB, PostgreSQL y plataformas en la nube como AWS, Render y Vercel. Para IoT usamos Arduino, ESP32, Raspberry Pi y MQTT."}$wb$::jsonb, 5),
  ($wb${"q":"¿En cuánto tiempo entregan un proyecto?","a":"Una landing page se entrega en 1 a 2 semanas, un e-commerce en 4 a 6 semanas y una app móvil completa entre 8 y 12 semanas. Trabajamos por etapas y cada semana ves el avance."}$wb$::jsonb, 6)
) as v(datos, orden)
where not exists (select 1 from web_bonding.contenido c where c.seccion = 'preguntas');

